package cn.iocoder.yudao.module.aigc.service;
import cn.iocoder.yudao.module.aigc.auth.*;
import cn.iocoder.yudao.framework.security.core.util.SecurityFrameworkUtils;
import cn.iocoder.yudao.framework.tenant.core.context.TenantContextHolder;
import cn.iocoder.yudao.module.system.service.auth.AdminAuthService;
import cn.iocoder.yudao.module.system.service.user.AdminUserService;
import cn.iocoder.yudao.module.system.controller.admin.auth.vo.AuthRegisterReqVO;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.data.redis.core.script.DefaultRedisScript;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.stereotype.Service;
import org.springframework.web.util.UriComponentsBuilder;
import java.net.*;
import java.net.http.*;
import java.time.Duration;
import java.security.*;
import java.util.*;
import java.util.function.Supplier;
import static cn.iocoder.yudao.module.aigc.auth.GoogleIdentityStore.AuthError;
@Service
public class GoogleAuthService {
 private final GoogleAuthConfig config=GoogleAuthConfig.load();private final GoogleIdentityVerifier verifier;
 private final StringRedisTemplate redis;private final ObjectMapper json;private final GoogleIdentityStore identities;private final AdminUserService users;private final AdminAuthService auth;
 private final SecureRandom random=new SecureRandom();private final HttpClient http=googleHttpClient();
 private static HttpClient googleHttpClient(){var builder=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(8)).followRedirects(HttpClient.Redirect.NEVER);String host=System.getenv("GOOGLE_PROXY_HOST");if(host!=null&&!host.isBlank())builder.proxy(ProxySelector.of(new InetSocketAddress(host,3129)));return builder.build();}
 private static final DefaultRedisScript<Long> TAKE=new DefaultRedisScript<>("if redis.call('get',KEYS[1])==ARGV[1] then redis.call('del',KEYS[1]);return 1 end return 0",Long.class);
 public GoogleAuthService(StringRedisTemplate redis,ObjectMapper json,JdbcTemplate db,PlatformTransactionManager manager,AdminUserService users,AdminAuthService auth){this.redis=redis;this.json=json;this.identities=new GoogleIdentityStore(db,manager);this.users=users;this.auth=auth;this.verifier=config.enabled()?new GoogleIdentityVerifier(config.clientId()):null;}
 public String random(){byte[] bytes=new byte[32];random.nextBytes(bytes);return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);}
 private String hash(String text){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private <T>T tenant(Supplier<T> action){Long old=TenantContextHolder.getTenantId();boolean ignored=TenantContextHolder.isIgnore();try{TenantContextHolder.setTenantId(1L);TenantContextHolder.setIgnore(false);return action.get();}finally{TenantContextHolder.setTenantId(old);TenantContextHolder.setIgnore(ignored);}}
 private Long owner(){Long id=SecurityFrameworkUtils.getLoginUserId();if(id==null||!Objects.equals(SecurityFrameworkUtils.getLoginUser().getTenantId(),1L))throw new AuthError(401,"请先登录原账号再关联 Google");return id;}
 private void require(){if(!config.enabled())throw new AuthError(503,config.disabledReason());}
 private void checkOrigin(String origin){if(!config.origin().equals(origin))throw new AuthError(403,"请从工作台页面发起 Google 登录");}
 private String key(String kind,String id){if(id==null||!id.matches("[A-Za-z0-9_-]{43}"))throw new AuthError(400,"登录流程已失效，请重新开始");return "zaomeng:google:"+kind+":"+id;}
 private void put(String kind,String id,Map<String,Object> value,int seconds){try{redis.opsForValue().set(key(kind,id),json.writeValueAsString(value),Duration.ofSeconds(seconds));}catch(AuthError e){throw e;}catch(Exception e){throw new AuthError(503,"登录状态暂不可用，请稍后重试");}}
 private Map<String,Object> take(String kind,String id,String proof){String key=key(kind,id),raw=redis.opsForValue().get(key);if(raw==null)throw new AuthError(400,"登录流程已过期或已使用，请重新开始");try{var value=json.readValue(raw,new com.fasterxml.jackson.core.type.TypeReference<Map<String,Object>>(){});if(proof!=null&&!MessageDigest.isEqual(hash(proof).getBytes(),value.get("proofHash").toString().getBytes()))throw new AuthError(400,"登录流程与当前浏览器不匹配");if(!Long.valueOf(1).equals(redis.execute(TAKE,List.of(key),raw)))throw new AuthError(400,"登录流程已使用，请重新开始");return value;}catch(AuthError e){throw e;}catch(Exception e){throw new AuthError(400,"登录状态校验失败");}}
 public Map<String,Object> configuration(){return Map.of("enabled",config.enabled(),"reason",config.disabledReason(),"localCallback",config.redirectUri().startsWith("http://localhost:"));}
 public Map<String,Object> start(Map<String,Object> body,String origin){require();checkOrigin(origin);String proof=Objects.toString(body.get("proof"),"");if(!proof.matches("[A-Za-z0-9_-]{43}"))throw new AuthError(400,"登录浏览器凭证无效");String action=Objects.toString(body.get("action"),"LOGIN");if(!Set.of("LOGIN","BIND").contains(action))throw new AuthError(400,"登录操作无效");Long user=action.equals("BIND")?owner():null;String state=random(),nonce=random(),pkce=random();var flow=new LinkedHashMap<String,Object>();flow.put("nonce",nonce);flow.put("verifier",pkce);flow.put("proofHash",hash(proof));flow.put("owner",user);flow.put("action",action);put("state",state,flow,600);String challenge=Base64.getUrlEncoder().withoutPadding().encodeToString(HexFormat.of().parseHex(hash(pkce)));String url=UriComponentsBuilder.fromUriString("https://accounts.google.com/o/oauth2/v2/auth").queryParam("client_id",config.clientId()).queryParam("redirect_uri",config.redirectUri()).queryParam("response_type","code").queryParam("scope","openid email profile").queryParam("state",state).queryParam("nonce",nonce).queryParam("code_challenge",challenge).queryParam("code_challenge_method","S256").queryParam("prompt","select_account").build().encode().toUriString();return Map.of("authorizeUrl",url);}
 public String callback(String state,String code,String error){require();try{var flow=take("state",state,null);if(error!=null)return config.origin()+"/#google-error/cancelled";if(code==null||code.isBlank()||code.length()>4096)throw new AuthError(400,"Google 授权码缺失");String form="grant_type=authorization_code&code="+enc(code)+"&client_id="+enc(config.clientId())+"&client_secret="+enc(config.clientSecret())+"&redirect_uri="+enc(config.redirectUri())+"&code_verifier="+enc(flow.get("verifier").toString());var request=HttpRequest.newBuilder(URI.create("https://oauth2.googleapis.com/token")).timeout(Duration.ofSeconds(15)).header("Content-Type","application/x-www-form-urlencoded").POST(HttpRequest.BodyPublishers.ofString(form)).build();var response=http.send(request,HttpResponse.BodyHandlers.ofString());if(response.statusCode()!=200||response.body().length()>100000){String reason="unknown";try{reason=json.readTree(response.body()).path("error").asText("unknown").replaceAll("[^a-z_]","");}catch(Exception ignored){}org.slf4j.LoggerFactory.getLogger(getClass()).warn("Google token exchange HTTP {}, error {}",response.statusCode(),reason);throw new AuthError(502,"Google 授权验证失败，请重新登录");}var token=json.readTree(response.body());var profile=verifier.verify(token.path("id_token").asText(),flow.get("nonce").toString());flow.remove("nonce");flow.remove("verifier");flow.put("subject",profile.subject());flow.put("email",profile.email());flow.put("name",profile.name());String ticket=random();put("ticket",ticket,flow,120);return config.origin()+"/#google-callback/"+ticket;}catch(Exception e){org.slf4j.LoggerFactory.getLogger(getClass()).warn("Google callback rejected: {}",e instanceof AuthError?e.getMessage():e.getClass().getSimpleName());return config.origin()+"/#google-error/failed";}}
 private String enc(String value){return URLEncoder.encode(value,java.nio.charset.StandardCharsets.UTF_8);}
 public Map<String,Object> exchange(Map<String,Object> body,String origin){require();checkOrigin(origin);String proof=Objects.toString(body.get("proof"),"");if(!proof.matches("[A-Za-z0-9_-]{43}"))throw new AuthError(400,"登录浏览器凭证无效");var flow=take("ticket",Objects.toString(body.get("ticket"),""),proof);Long target=flow.get("owner")==null?null:((Number)flow.get("owner")).longValue();if(target!=null&&!target.equals(owner()))throw new AuthError(401,"账号状态已变化，请重新登录后关联");var profile=new GoogleIdentityVerifier.Profile(flow.get("subject").toString(),flow.get("email").toString(),flow.get("name").toString());return tenant(()->{long user=identities.resolve(profile,target,()->{var registration=new AuthRegisterReqVO();registration.setUsername("g"+UUID.randomUUID().toString().replace("-","").substring(0,24));registration.setNickname(profile.name());registration.setPassword(random().substring(0,16));return users.registerUser(registration).getId();});if(target!=null)return Map.of("bound",true);return Map.of("bound",false,"tokens",auth.loginVerifiedSocialUser(user));});}
 public Map<String,Object> linked(){Long user=owner();return identities.linked(user);}
}
